import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Bulanıklaştırma ve pikselleştirme, fotoğraftaki hassas ayrıntıyı gizler. Yüzler, plakalar ve metinler görünmez olur.</p>\n<p>Doğru yöntem, gizlenecek ayrıntıya bağlıdır. Yüz için bulanıklaştırma, plaka için pikselleştirme daha güvenli olabilir.</p>\n<p>Bu kılavuz, iki yöntemin nasıl çalıştığını, fırça ve tam görsel modlarını ve yüzleri doğru gizlemenin yollarını anlatıyor.</p>\n<h2 id=\"what-blur-does\">Bulanıklaştırma görsele ne yapar?</h2>\n<p>Bulanıklaştırma, pikselleri yumuşatır. Keskin kenarlar kaybolur; ayrıntı tanınmaz hâle gelir.</p>\n<p>Bulanıklaştırma derecesi ayarlanabilir. Hafif bulanıklık yumuşatır; güçlü bulanıklık tamamen gizler.</p>\n<p>Bulanıklaştırma, fotoğrafın doğal görünmesini sağlar. Arka plan bulanıklığı, portrelerde hoş görünür.</p>\n<h2 id=\"what-pixelate-does\">Pikselleştirme görsele ne yapar?</h2>\n<p>Pikselleştirme, görseli büyük renk bloklarına böler. Ayrıntı, blokların altında kaybolur.</p>\n<p>Blok boyutu ayarlanabilir. Büyük bloklar daha güvenli gizler; küçük bloklar ayrıntıyı sızdırır.</p>\n<p>Pikselleştirme, sansürün klasik görünümüdür. Televizyonlarda yüzler böyle gizlenir.</p>\n<h2 id=\"why-censor-images\">İnsanlar fotoğrafları neden bulanıklaştırır ve pikselleştirir?</h2>\n<p>Gizlilik için. Çocukların yüzleri, plakalar ve adresler paylaşılmamalıdır.</p>\n<p>Yasal zorunluluk için. Bazı ülkelerde yüzleri gizlemek yasal gerekliliktir.</p>\n<p>Odak için. Bulanık arka plan, konuyu öne çıkarır.</p>\n<h2 id=\"brush-area-mode\">Fırça alanı modu: ayrıntıların üzerini boyamak</h2>\n<p>Fırça modu, yalnızca boyadığınız alanı gizler; yüzün üzerini boyarsınız, fotoğrafın geri kalanı net kalır.</p>\n<p>Araçta fırça boyutunu ayarlayabilirsiniz; yüz için geniş, plaka için dar fırça kullanın.</p>\n<p>Fırça, hassas kontrol sağlar. Yalnızca gizlenmesi gereken yer gizlenir.</p>\n<h2 id=\"whole-image-mode\">Tam görsel modu: her şeyi bulanıklaştırmak</h2>\n<p>Araçtaki tam görsel modu, fotoğrafın tamamını bulanıklaştırır; böyle kareler arka plan olarak kullanılır.</p>\n<p>Araçtaki bu mod, portre arka planlarında çok hoş durur; konu net kalırken arka plan yumuşacık olur.</p>\n<p>Tam görsel modunu gizlilik için kullanmayın; her şeyi bulanıklaştırmak, fotoğrafı anlamsız bırakır.</p>\n<h2 id=\"smooth-blur-strength\">Yumuşak bulanıklık gücü: ne kadar güçlü, yeterince güçlü?</h2>\n<p>Hafif bulanıklık, ayrıntıyı yumuşatır ama gizlemez. Yüz hâlâ tanınır.</p>\n<p>Güçlü bulanıklık, yüzü tanınmaz yapar. Güvenlik için güçlü kullanın.</p>\n<p>Gücü test edin. Bulanıklaştırdıktan sonra fotoğrafı uzaktan bakın; yüz tanınmıyorsa yeterlidir.</p>\n<h2 id=\"mosaic-block-size\">Mozaik blok boyutu: büyük bloklar, daha güvenli sansür</h2>\n<p>Blok boyutu büyüdükçe sansür güçlenir. Küçük bloklar, ayrıntıyı sızdırır.</p>\n<p>Plakalar için büyük blok kullanın. Harfler okunmamalıdır.</p>\n<p>Blok boyutunu test edin. Mozaikten sonra metni okumaya çalışın; okunmuyorsa yeterlidir.</p>\n<h2 id=\"brush-size-settings\">Fırça boyutu: aracı ayrıntıya uydurmak</h2>\n<p>Fırçayı gizlenecek ayrıntıdan biraz büyük tutun; küçük fırça, kenarlarda açık noktalar bırakır.</p>\n<p>Araçta yüz gizlerken geniş fırça alın; plaka gibi küçük ayrıntılarda dar fırça yeterlidir.</p>\n<p>Fırçayı gizlenecek alanın kenarlarından geçirerek boyayın; tek açık nokta bile sansürü bozar.</p>\n<h2 id=\"hiding-faces\">Yüzleri doğru gizlemek</h2>\n<p>Yüzün tamamını gizleyin. Yalnızca gözleri kapatmak yeterli değildir; yüz hâlâ tanınır.</p>\n<p>Güçlü bulanıklık ya da büyük blok kullanın. Hafif gizleme, yapay zekâyla geri alınabilir.</p>\n<p>Çocukların yüzlerini her zaman gizleyin. Çocuk gizliliği, en katı kuraldır.</p>\n<h2 id=\"hiding-text-and-numbers\">Metin, sayı ve adres gizlemek</h2>\n<p>Metin için pikselleştirme daha güvenlidir. Bulanık metin, bazen okunabilir.</p>\n<p>Plaka ve kimlik numaraları için büyük blok kullanın. Rakamlar okunmamalıdır.</p>\n<p>Adres ve telefon için de aynı kural geçerlidir. Kişisel bilgi, tamamen gizlenmelidir.</p>\n<h2 id=\"hiding-backgrounds\">Odak ve gizlilik için arka planı bulanıklaştırmak</h2>\n<p>Bulanık arka plan, konuyu öne çıkarır. Portrelerde hoş görünür.</p>\n<p>Arka plandaki kişisel ayrıntı da gizlenir. Adres tabelaları ve plakalar bulanıklaşır.</p>\n<p>Arka plan bulanıklığını abartmayın. Hafif bulanıklık doğal görünür; güçlü bulanıklık yapay durur.</p>\n<h2 id=\"formats-and-transparency\">Formatlar ve saydamlık</h2>\n<p>Sansürlü fotoğraflar için JPG kullanın. Dosya küçülür ve her cihazda açılır.</p>\n<p>Saydam görsellerde PNG tercih edin. JPG, saydam alanları doldurur.</p>\n<p>Bulanıklaştırma, formatı değiştirmez. Çıktı formatını kendiniz seçersiniz.</p>\n<h2 id=\"privacy-local-processing\">Gizlilik: hiçbir şey yüklemeden sansürlemek</h2>\n<p>Sansür aracı tamamen tarayıcıda çalışır. Fotoğraflarınız sunucuya yüklenmez.</p>\n<p>Bu, hassas fotoğraflar için önemlidir. Çocuk ve belge fotoğraflarını güvenle düzenleyebilirsiniz.</p>\n<p>İşlem bitince hiçbir iz kalmaz. Fotoğraflarınız cihazınızdan çıkmaz.</p>\n<h2 id=\"common-mistakes\">Görsel sansürlerken yaygın hatalar</h2>\n<p>En yaygın hata, hafif gizlemektir. Hafif bulanıklık, yüzü tanınır bırakır.</p>\n<p>Bir başka hata, noktayı atlamaktır. Fırçayla boyanmayan küçük alan, sansürü bozar.</p>\n<p>Üçüncü hata, yalnızca gözleri kapatmaktır. Yüz, gözler olmadan da tanınır.</p>\n<h2 id=\"censoring-workflow\">Güvenli paylaşım için bir akış</h2>\n<p>Önce gizlenecekleri listeleyin. Yüzler, plakalar, adresler ve metinler.</p>\n<p>Sonra her birini fırçayla gizleyin. Güçlü bulanıklık ya da büyük blok kullanın.</p>\n<p>Son olarak sonucu kontrol edin. Paylaşmadan önce her ayrıntının gizlendiğinden emin olun.</p>\n<h2 id=\"blurring-for-video-thumbnails\">Video küçük resimleri ve kapakları için bulanıklaştırma</h2>\n<p>Küçük resimlerde arka planı bulanıklaştırın. Konu öne çıkar ve tıklanma artar.</p>\n<p>Kapak görsellerinde hafif bulanıklık kullanın. Doğal görünüm korunmalıdır.</p>\n<p>Metin ekleyecekseniz arka planı bulanıklaştırın. Yazı, düz zeminde okunur.</p>\n<p>Özetle: gizlenecek ayrıntıyı güçlü gizleyin, hafif bırakmayın. Adımlar için <a href=\"/tr/blog/gorsel-nasil-bulaniklastirilir-piksellestirilir\">Görsel bulanıklaştırma ve pikselleştirme nasıl yapılır</a> yazısına bakın; karşılaştırma için <a href=\"/tr/blog/bulaniklastirma-vs-piksellestirme-gorsel\">bulanıklaştırma ve pikselleştirme karşılaştırması</a> yardımcı olur. Konum verisi için <a href=\"/tr/gorsel-metadata-kaldir\">meta veri kaldırma</a> hazırdır; araç ise <a href=\"/tr/gorsel-bulaniklastir-piksellestir\">bulanıklaştırma ve pikselleştirme</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Bir yüzün bulanıklığı sonradan kaldırılabilir mi?","answer":"Hafif bulanıklık bazen yapay zekâyla kısmen geri alınabilir; güçlü bulanıklık geri alınamaz. Güvenlik için güçlü bulanıklık ya da büyük bloklu pikselleştirme kullanın. Yüzün tamamını gizleyin; yalnızca gözleri kapatmak yeterli değildir."},{"question":"Plaka gizlemek için pikselleştirme bulanıklaştırmadan daha mı güvenli?","answer":"Evet. Bulanık metin bazen okunabilir; pikselleştirme harfleri blokların altında tamamen gizler. Plakalar için büyük blok kullanın. Gizledikten sonra metni okumaya çalışın; okunmuyorsa yeterlidir."},{"question":"Telefonda bir yüzdeki yüzü nasıl bulanıklaştırırım?","answer":"Bulanıklaştırma aracını telefon tarayıcısında açın, fotoğrafı yükleyin ve fırça moduyla yüzün üzerini boyayın. Fırça boyutunu yüze göre ayarlayın. Güçlü bulanıklık kullanın ve sonucu indirmeden önce kontrol edin."},{"question":"Portrenin arka planının tamamını bulanıklaştırmalı mıyım?","answer":"Gerekmez; hafif bulanıklık yeterlidir. Bulanık arka plan konuyu öne çıkarır ve hoş görünür. Güçlü bulanıklık yapay durur. Arka plandaki kişisel ayrıntı varsa o bölgeleri ayrıca gizleyin."},{"question":"Boyarken bir noktayı atlarsam ne yapmalıyım?","answer":"Fırçayla atlanan noktayı yeniden boyayın. Kenarların üzerinden geçtiğinizden emin olun; açık kalan küçük alan sansürü bozar. İndirmeden önce sonucu yakınlaştırarak kontrol edin."},{"question":"Fotoğrafı bulanıklaştırmak konum verilerini siler mi?","answer":"Hayır, bulanıklaştırma EXIF verilerini silmez; konum bilgisi dosyada kalır. Konumu silmek istiyorsanız meta veri kaldırma aracını kullanın. Paylaşmadan önce konum verisini kontrol edin."}];
